<?php
declare(strict_types=1);
function oauth_config(): array { $v=setting('oauth_config');if(!$v)throw new RuntimeException('Configure a aplicação OAuth em /configurar');$c=decrypt_value($v);if(empty($c['client_id'])||empty($c['client_secret']))throw new RuntimeException('OAuth não configurado');return $c; }
function http_request(string $url,?string $token=null,?array $post=null,bool $pdf=false): mixed {
 if(!str_starts_with($url,'https://api.mercadolibre.com/'))throw new RuntimeException('Destino não permitido');
 if(!function_exists('curl_init'))throw new RuntimeException('Extensão PHP cURL necessária');$h=curl_init($url);$headers=['Accept: '.($pdf?'application/pdf':'application/json')];if($token)$headers[]='Authorization: Bearer '.$token;
 $options=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>15,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_HTTPHEADER=>$headers,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS];if($post!==null){$options[CURLOPT_POST]=true;$options[CURLOPT_POSTFIELDS]=http_build_query($post);$options[CURLOPT_HTTPHEADER][]='Content-Type: application/x-www-form-urlencoded';}curl_setopt_array($h,$options);$data=curl_exec($h);$status=curl_getinfo($h,CURLINFO_RESPONSE_CODE);$type=curl_getinfo($h,CURLINFO_CONTENT_TYPE);curl_close($h);if($data===false||$status<200||$status>=300)throw new RuntimeException('MELI_READ_FAILED');if($pdf){if(!str_contains((string)$type,'application/pdf'))throw new RuntimeException('Etiqueta indisponível');return $data;}return json_decode($data,true,64,JSON_THROW_ON_ERROR);
}
function token_request(array $fields): array {$c=oauth_config();$t=http_request('https://api.mercadolibre.com/oauth/token',null,array_merge(['client_id'=>$c['client_id'],'client_secret'=>$c['client_secret']],$fields));if(empty($t['access_token'])||empty($t['refresh_token'])||!is_numeric($t['expires_in']??null)||empty($t['user_id']))throw new RuntimeException('INVALID_OAUTH_RESPONSE');return $t;}
function access_token(string $id): string {return transaction(function()use($id){$a=sql('SELECT * FROM accounts WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$a)throw new RuntimeException('Conta não conectada');$t=decrypt_value($a['tokens']);if((int)$a['expires_at']<time()+60){$t=token_request(['grant_type'=>'refresh_token','refresh_token'=>$t['refresh_token']]);sql('UPDATE accounts SET tokens=?,expires_at=? WHERE id=?',[encrypt_value($t),time()+(int)$t['expires_in'],$id]);}return $t['access_token'];});}
function resource_valid(string $topic,string $resource): bool { $patterns=['orders_v2'=>'~^/orders/[0-9]+$~D','items'=>'~^/items/MLB[0-9]+$~D','shipments'=>'~^/shipments/[0-9]+$~D'];return isset($patterns[$topic])&&preg_match($patterns[$topic],$resource)===1; }
function read_resource(string $id,string $resource): array {if(!preg_match('~^/(users/me|users/[0-9]+/items/search|orders/[0-9]+|items/MLB[0-9]+|shipments/[0-9]+)$~D',$resource))throw new RuntimeException('Recurso não permitido');return http_request('https://api.mercadolibre.com'.$resource,access_token($id));}
function import_order(array $o,string $account): void {if((string)($o['seller']['id']??'')!==$account||!isset($o['id'],$o['total_amount'])||!is_array($o['order_items']??null))throw new RuntimeException('INVALID_ORDER');$paid=($o['status']??'')==='paid'&&!empty($o['payments']);foreach(($o['payments']??[]) as $p)if(($p['status']??'')!=='approved')$paid=false;
 transaction(function()use($o,$account,$paid){$id=(string)$o['id'];$existing=sql('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if($existing&&($existing['simulated']||(string)$existing['account_id']!==$account))throw new RuntimeException('ORDER_ACCOUNT_MISMATCH');$lines=[];$mapped=true;foreach($o['order_items'] as $item){$p=sql('SELECT p.* FROM listings l JOIN products p ON l.sku=p.sku WHERE l.external_id=?',[$item['item']['id']??''])->fetch(PDO::FETCH_ASSOC);if(!$p){$mapped=false;continue;}$q=$item['quantity']??0;if(!is_int($q)||$q<1)throw new RuntimeException('INVALID_QUANTITY');$lines[]=['sku'=>$p['sku'],'quantity'=>$q,'cost'=>$p['cost']];}$status=($o['status']??'')==='cancelled'?'cancelled':(!$mapped?'unmapped':($paid?'awaiting_approval':'pending'));$shipment=isset($o['shipping']['id'])?(string)$o['shipping']['id']:null;
 if(!$existing){sql('INSERT INTO orders(id,account_id,status,total,payment_confirmed,shipment_id) VALUES(?,?,?,?,?,?)',[$id,$account,$status,(int)round($o['total_amount']*100),(int)$paid,$shipment]);audit('order.imported',$id,'success','mercado-livre');}else sql('UPDATE orders SET payment_confirmed=?,status=?,shipment_id=? WHERE id=?',[(int)$paid,$status,$shipment,$id]);
 if(!$existing||!$existing['supplier_order_id']){sql('DELETE FROM order_lines WHERE order_id=?',[$id]);if($mapped)foreach($lines as $l)sql('INSERT INTO order_lines(order_id,sku,quantity,unit_cost) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)',[$id,$l['sku'],$l['quantity'],$l['cost']]);}
 });}
function process_queue(int $limit=5): array { $lock=sql("SELECT GET_LOCK('smartdrop_read_worker',0)")->fetchColumn();if((int)$lock!==1)return ['processed'=>0,'busy'=>true];$done=0;$failed=0;try{$rows=sql("SELECT * FROM webhook_events WHERE status IN ('pending','failed') AND attempts<5 AND next_run<=? ORDER BY created_at LIMIT ".max(1,min(10,$limit)),[time()])->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $event){try{if(!resource_valid($event['topic'],$event['resource']))throw new RuntimeException('INVALID_RESOURCE');$r=read_resource($event['account_id'],$event['resource']);$owner=$event['topic']==='items'?($r['seller_id']??null):($event['topic']==='orders_v2'?($r['seller']['id']??null):($r['sender_id']??null));if((string)$owner!==$event['account_id'])throw new RuntimeException('OWNER_MISMATCH');if($event['topic']==='orders_v2')import_order($r,$event['account_id']);transaction(function()use($event){sql("UPDATE webhook_events SET status='completed',attempts=attempts+1,last_error=NULL WHERE id=?",[$event['id']]);audit('notification.read',$event['id'],'success','cron');});$done++;}catch(Throwable){$attempt=(int)$event['attempts']+1;sql("UPDATE webhook_events SET status='failed',attempts=?,next_run=?,last_error='REMOTE_READ_FAILED' WHERE id=?",[$attempt,time()+min(3600,30*(2**$attempt)),$event['id']]);$failed++;}}}finally{sql("SELECT RELEASE_LOCK('smartdrop_read_worker')");}return ['processed'=>$done,'failed'=>$failed];}
